import{_ as o,a0 as d,w as p,s as r,I as i,x as e,a1 as t,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 中的模糊文件搜索 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中的模糊文件搜索 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中的模糊文件搜索 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中的模糊文件搜索 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux","title":"Linux 中的模糊文件搜索","tag":"202306","desc":""},"relativePath":"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux.md","filePath":"[post].md"}'),h={name:"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux.md"};function f(c,s,g,b,k,u){const a=d("Link");return p(),r("div",null,[s[26]||(s[26]=i("h1",{id:"linux-中的模糊文件搜索",tabindex:"-1"},[e("Linux 中的模糊文件搜索 "),i("a",{class:"header-anchor",href:"#linux-中的模糊文件搜索","aria-label":"Permalink to “Linux 中的模糊文件搜索”"},"​")],-1)),s[27]||(s[27]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/24/001013mc7chh224c7uls8h.jpg",alt:""})],-1)),s[28]||(s[28]=i("blockquote",null,[i("p",null,"像 fzf 和 fzy 這樣的現代工具將 Linux 終端中的文件搜索提升到了一個新的水平。")],-1)),i("p",null,[s[2]||(s[2]=e("在 Linux 命令列中，如何 ",-1)),t(a,{href:"https://learnubuntu.com:443/find-files/"},{default:l(()=>[...s[0]||(s[0]=[e("搜索文件",-1)])]),_:1}),s[3]||(s[3]=e("？你可以使用 ",-1)),t(a,{href:"https://linuxhandbook.com:443/find-command-examples/"},{default:l(()=>[...s[1]||(s[1]=[e("find 命令",-1)])]),_:1}),s[4]||(s[4]=e("。這是標準答案，沒有問題。",-1))]),s[29]||(s[29]=n('<p>通常，你鍵入帶有搜索參數的命令，按回車鍵，然後它會顯示搜索結果。</p><p>你可以通過模糊搜索來提升終端中的文件搜索體驗。</p><p>模糊搜索是一種近似搜索算法或技術。在這種搜索中，通過名稱搜索指定位置的文件，並實時顯示結果給用户。</p><p>模糊搜索在網絡搜索引擎中很受歡迎，用户開始輸入術語後，它會開始顯示與該術語相關的結果。</p><p>在本文中，我將討論兩個命令列工具，它們可以讓你在 Linux 中執行模糊搜索：</p><ul><li><code>fzf</code>：模糊查找工具</li><li><code>fzy</code>：模糊選擇工具</li></ul><h3 id="fzf-linux-中的模糊查找工具" tabindex="-1">fzf：Linux 中的模糊查找工具 <a class="header-anchor" href="#fzf-linux-中的模糊查找工具" aria-label="Permalink to “fzf：Linux 中的模糊查找工具”">​</a></h3><p><code>fzf</code> 是一款可用於 Linux 的模糊搜索工具，你可以通過它進行交互式文件搜索。</p><p>在 Ubuntu 中安裝 <code>fzf</code>，打開終端並運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fzf</span></span></code></pre></div><p>雖然 <code>fzf</code> 本身可以正常工作，但最好與其他工具配合使用，以充分發揮其功能。</p><h4 id="使用-fzf" tabindex="-1">使用 fzf <a class="header-anchor" href="#使用-fzf" aria-label="Permalink to “使用 fzf”">​</a></h4><p>打開終端並運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf</span></span></code></pre></div><p>這將打開一個 <code>fzf</code> 提示符，在當前工作目錄中搜索文件。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-default.svg" alt="在終端中運行 fzf 命令"></p><h5 id="為-fzf-應用邊框" tabindex="-1">為 fzf 應用邊框 <a class="header-anchor" href="#為-fzf-應用邊框" aria-label="Permalink to “為 fzf 應用邊框”">​</a></h5><p>你可以使用 <code>--border</code> 選項為 <code>fzf</code> 應用邊框，有多種邊框可用，如 <code>rounded</code>（圓角）、<code>sharp</code>（尖角）等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --border=rounded</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzf-border.svg" alt="運行帶有邊框選項設置為 rounded 和 sharp 的 fzf 命令"></p><h5 id="應用背景和前景顏色" tabindex="-1">應用背景和前景顏色 <a class="header-anchor" href="#應用背景和前景顏色" aria-label="Permalink to “應用背景和前景顏色”">​</a></h5><p>使用顏色屬性，你可以為 <code>fzf</code> 設置 ANSI 顏色，可以作為背景、前景或兩者都設置。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-colored.svg" alt="為 fzf 應用顏色，用户指定了顏色"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --color=&quot;bg:black,fg:yellow&quot;</span></span></code></pre></div><p>你可以串聯這些選項，使 <code>fzf</code> 在視覺上更加美觀。</p><p>現在，讓我展示一些 <code>fzf</code> 模糊搜索的實際用法。</p><h4 id="使用-fzf-在-bash-歷史中進行搜索" tabindex="-1">使用 fzf 在 Bash 歷史中進行搜索 <a class="header-anchor" href="#使用-fzf-在-bash-歷史中進行搜索" aria-label="Permalink to “使用 fzf 在 Bash 歷史中進行搜索”">​</a></h4><p>當然，Bash 歷史記錄中有 <code>CTRL+R</code> 的反向搜索功能。但如果你想使用 <code>fzf</code> 來獲得更好的外觀，可以運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history | fzf</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/search-within-bash-history.svg" alt="使用 fzf 模糊搜索在 bash 歷史中進行搜索"></p><h4 id="使用-fzf-結合-tree-命令" tabindex="-1">使用 fzf 結合 tree 命令 <a class="header-anchor" href="#使用-fzf-結合-tree-命令" aria-label="Permalink to “使用 fzf 結合 tree 命令”">​</a></h4>',31)),i("p",null,[t(a,{href:"https://linuxhandbook.com:443/tree-command/"},{default:l(()=>[...s[5]||(s[5]=[e("tree 命令",-1)])]),_:1}),s[6]||(s[6]=e(" 會列出文件和目錄，並顯示它們的層級關係。",-1))]),s[30]||(s[30]=n('<p>使用 <code>fzf</code> 結合 <code>tree</code> 命令可以幫助你找到特定文件的絕對路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tree -afR /home/$USER | fzf</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/tree-afr.svg" alt="運行 Tree 命令並將輸出傳遞給模糊搜索"></p><blockquote><p>💡 上述命令會調用 <code>tree</code> 並以遞歸方式列出包括隱藏文件在內的所有文件（<code>-a</code>）。同時，<code>-f</code> 選項告訴 <code>tree</code> 列出完整路徑。</p></blockquote><h4 id="在-fzf-中預覽文件" tabindex="-1">在 fzf 中預覽文件 <a class="header-anchor" href="#在-fzf-中預覽文件" aria-label="Permalink to “在 fzf 中預覽文件”">​</a></h4><p>有時，如果你可以獲得你搜索的文件的小型預覽，那會很有幫助。</p><p>幸運的是，<code>fzf</code> 提供了一個預覽選項。你可以使用 <code>--preview</code> 來訪問它。我在這裏使用 <code>find</code> 命令使其更加有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;less {}&#39;</span></span></code></pre></div><p>在這裏，當你滾動瀏覽結果時，它將使用 <code>less</code> 顯示文本文件。</p><blockquote><p>🚧 如果你使用其他命令如 <code>ls</code> 等，請不要使用 <code>-l</code> 等選項，因為這將顯示額外的詳細信息（文件權限）。這些額外的詳細信息會破壞 <code>fzf</code> 預覽所需的格式。在使用預覽功能時，輸入到 <code>fzf</code> 的應該只是文件名。</p></blockquote><p>如果你已安裝了 <code>bat</code>，也可以使用它來預覽文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;bat --color always {}&#39;</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/bashrc-preview-in-fzf.png" alt="使用 bat 作為 FZF 預覽功能的文本查看器"></p><p>對於 Ubuntu 用户，可以使用 <code>batcat</code> 來調用 <code>bat</code>。因此運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;batcat --color always {}&#39;</span></span></code></pre></div>',15)),i("blockquote",null,[i("p",null,[s[8]||(s[8]=e("💡 ",-1)),t(a,{href:"https://linuxhandbook.com:443/linux-alias-command/"},{default:l(()=>[...s[7]||(s[7]=[e("為這些命令創建別名",-1)])]),_:1}),s[9]||(s[9]=e("，這樣你就不需要反覆輸入它們。",-1))])]),s[31]||(s[31]=n(`<h4 id="從任何地方使用-fzf-進入任何目錄-高級技巧" tabindex="-1">從任何地方使用 fzf 進入任何目錄（高級技巧） <a class="header-anchor" href="#從任何地方使用-fzf-進入任何目錄-高級技巧" aria-label="Permalink to “從任何地方使用 fzf 進入任何目錄（高級技巧）”">​</a></h4><p>這比以前要複雜一些。在這裏，你不能直接將 <code>fzf</code> 和 <code>cd</code> 連接在一起，因為它們是不同的進程。</p><p>你可以創建一個別名並使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd $(find /home/$USER -type d | fzf)</span></span></code></pre></div><p>或者，你可以按照下面解釋的方法進行操作。</p><p>為此，你可能需要在 <code>bashrc</code> 中添加一個函數。讓我將這個函數稱為 <code>finder</code>。現在請添加以下行到你的 <code>bashrc</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>finder() {</span></span>
<span class="line"><span>  local dir</span></span>
<span class="line"><span>  dir=$(find required/location/to/search/and/enter -type d | fzf)</span></span>
<span class="line"><span>  if [[ -n &quot;$dir&quot; ]]; then</span></span>
<span class="line"><span>    cd &quot;$dir&quot; || return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,7)),i("p",null,[s[11]||(s[11]=e("現在，你應該 ",-1)),t(a,{href:"https://itsfoss.com/change-directories/"},{default:l(()=>[...s[10]||(s[10]=[e("輸入路徑",-1)])]),_:1}),s[12]||(s[12]=e("，其中包含你要搜索並進入的目錄。",-1))]),s[32]||(s[32]=n('<p>例如，我已經使用 <code>/home/$USER</code> 替換了該部分，表示我要從任何位置進入我的主目錄中的任何目錄。</p><p>保存你的 <code>bashrc</code> 文件後，要麼重啓終端，要麼運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source ~/.bashrc</span></span></code></pre></div><p>之後，你可以在終端上運行 <code>finder</code> 命令，一旦找到要進入的目錄，按回車鍵即可。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-cd-combo.svg" alt="使用 fzf 命令結合 cd 命令進入任意目錄"></p><h4 id="將選擇內容複製到剪貼板" tabindex="-1">將選擇內容複製到剪貼板 <a class="header-anchor" href="#將選擇內容複製到剪貼板" aria-label="Permalink to “將選擇內容複製到剪貼板”">​</a></h4><p>到目前為止，你已經瞭解瞭如何使用 <code>fzf</code>，它提供了搜索結果或預覽。</p><p>現在，如果你想要複製某個項目的位置，你不必手動執行此操作。也有相應的解決方案。</p><p>首先，確保你已經安裝了 <code>xclip</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install xclip</span></span></code></pre></div><p>然後像這樣將其傳遞給 <code>xclip</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf | xclip -selection clipboard</span></span></code></pre></div><p>這將複製你按下回車鍵的那些行到剪貼板上。</p><h4 id="其他用途" tabindex="-1">其他用途 <a class="header-anchor" href="#其他用途" aria-label="Permalink to “其他用途”">​</a></h4><p>正如我之前所説，你可以使用任何涉及大量文本，並希望交互式搜索特定內容的命令。</p><ul><li><code>cat ~/.bashrc | fzf</code> - 在 Bashrc 文件中搜索</li><li><code>lsblk | fzf</code> - 在鎖定設備列表中搜索</li><li><code>ps -aux | fzf</code> - 在進程列表中搜索</li></ul><h3 id="另一個選擇-fzy-模糊選擇器" tabindex="-1">另一個選擇：Fzy，模糊選擇器 <a class="header-anchor" href="#另一個選擇-fzy-模糊選擇器" aria-label="Permalink to “另一個選擇：Fzy，模糊選擇器”">​</a></h3><p>與 <code>fzf</code> 不同，<code>fzy</code> 是一個模糊選擇器，它會根據輸入提供一個菜單供你選擇。</p><p>例如，如果你將 <code>fzy</code> 與 <code>ls</code> 命令一起使用，它將給你提供一個類似菜單的界面。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzy-ls.svg" alt="使用 ls 命令的 fzy 命令"></p><p>默認情況下，它會顯示十個條目。</p><h4 id="使用-fzy-進入目錄" tabindex="-1">使用 fzy 進入目錄 <a class="header-anchor" href="#使用-fzy-進入目錄" aria-label="Permalink to “使用 fzy 進入目錄”">​</a></h4><p>與 <code>fzf</code> 類似，你也可以使用 <code>fzy</code> 進入當前工作目錄中的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd $(find -type d | fzy)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzy-cd.svg" alt=""></p><h4 id="使用任何編輯器打開文件" tabindex="-1">使用任何編輯器打開文件 <a class="header-anchor" href="#使用任何編輯器打開文件" aria-label="Permalink to “使用任何編輯器打開文件”">​</a></h4><p>或者使用你喜歡的編輯器打開文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano $(find -type f | fzy)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzy-nano.svg" alt=""></p><h3 id="附加內容-自定義文件和圖像預覽" tabindex="-1">附加內容：自定義文件和圖像預覽 <a class="header-anchor" href="#附加內容-自定義文件和圖像預覽" aria-label="Permalink to “附加內容：自定義文件和圖像預覽”">​</a></h3><p>下面的命令將在 <strong>Ubuntu</strong> 中打開一個專門的自定義提示符，用於模糊搜索，你可以通過滾動來預覽文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --color=&quot;bg:black,fg:yellow&quot; --preview &#39;batcat --color always {}&#39; --preview-window=bottom</span></span></code></pre></div><p>為了方便訪問，可以在你的 <code>bashrc</code> 文件中為此創建一個別名。</p><p>或者在使用 <code>timg</code> 命令列圖像查看器時，在 <code>fzf</code> 中進行圖像預覽並滾動。使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install timg</span></span></code></pre></div><blockquote><p>🚧 請注意，圖像查看器無法正確顯示圖像，因為這不是 <code>fzf</code> 預覽的主要目的。</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --preview &#39;timg -g 200x100 {}&#39; --preview-window=right:90</span></span></code></pre></div><p>對於那些喜歡折騰的人，可以嘗試對此部分進行優化。</p><h3 id="現代化的替代方案" tabindex="-1">現代化的替代方案 <a class="header-anchor" href="#現代化的替代方案" aria-label="Permalink to “現代化的替代方案”">​</a></h3><p>大多數 Linux 命令都是從 UNIX 時代繼承下來的。它們雖然老舊，但功能如預期。但這並不意味着它們不能改進。</p><p>我的意思是，你不需要重新發明輪子，但你總是可以努力改進輪子。</p><p>像 <code>fzf</code> 和 <code>fzy</code> 這樣的現代化工具將 Linux 終端中的文件搜索提升到了一個新的水平。以下是一些其他有趣的命令列工具。</p><p>我嘗試給出了這些模糊搜索工具的一些實際示例。希望你對它們感到足夠有啓發性。如果你打算使用它們，請在評論中告訴我。</p><p><em>（題圖：MJ/d25e71fa-f24e-49be-9579-e0520a8f6e18）</em></p><hr>',45)),i("p",null,[s[14]||(s[14]=e("via: ",-1)),t(a,{href:"https://itsfoss.com/fuzzy-file-search-linux/"},{default:l(()=>[...s[13]||(s[13]=[e("https://itsfoss.com/fuzzy-file-search-linux/",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("作者：",-1)),t(a,{href:"https://itsfoss.com/author/sreenath/"},{default:l(()=>[...s[15]||(s[15]=[e("Sreenath",-1)])]),_:1}),s[19]||(s[19]=e(" 選題：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[16]||(s[16]=[e("lkxed",-1)])]),_:1}),s[20]||(s[20]=e(" 譯者：ChatGPT 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const x=o(h,[["render",f]]);export{y as __pageData,x as default};
